from pathlib import Path
import json,html,csv
R=Path(__file__).resolve().parent
posts=json.loads((R/'posts.json').read_text());e=html.escape
cards=[]
for p in posts:
 imgs=''.join(f'<a href="images/{p["id"]}-{i:02}.jpg" data-post="{p["id"]}" data-slide="{i}"><img src="images/{p["id"]}-{i:02}.jpg" loading="lazy" alt="{p["id"]} slide {i}"></a>' for i in range(1,p['slides']+1))
 cards.append(f'''<article id="{p['id']}" data-style="{p['style']}"><div class="posthead"><span>{p['number']:02} / {p['id']}</span><span>{p['slides']} {'slides' if p['slides']>1 else 'image'}</span></div><h2>{e(p['title'].replace(chr(10),' '))}</h2><p class="style">{p['style_name']}</p><div class="slides">{imgs}</div><p class="hint">{'Scroll sideways to see all five slides. ' if p['slides']>1 else ''}Click any image for full view.</p><details><summary>Caption and source</summary><p class="caption">{e(p['caption'])}</p><button onclick="navigator.clipboard.writeText(DATA.find(p=>p.id===this.dataset.id).caption).then(()=>this.textContent='Copied')" data-id="{p['id']}">Copy caption</button><p class="source">{p['source']}_FINAL_PRIMARY.jpg<br>{'Conservative waistband crop applied.' if p['crop']['waistband_crop'] else 'Real shorts or jeans; no brief silhouette.'}</p></details><label class="review">Your review <select data-review="{p['id']}"><option value="">Not reviewed</option><option>Approved</option><option>Needs changes</option><option>Hold</option></select></label><textarea data-note="{p['id']}" placeholder="Notes for this post" rows="2"></textarea></article>''')
rotation=[]
orders=[[1,7,3,6,2,8,4,5],[3,8,2,5,7,4,6,1],[6,4,7,1,5,2,8,3]]
for rnd,order in enumerate(orders):
 for style in order:rotation.append(f'S{style:02}-'+ 'ABC'[rnd])
fields=['post_id','publication_date','platform','post_url','topic','source_photo','style','reach','likes','comments','saves','shares','profile_visits','follows','product_trials','paying_customers','measurement_date','tracking_evidence','notes']
with (R/'results-ledger.csv').open('w') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for p in posts:w.writerow(dict(post_id=p['id'],topic=p['topic'],source_photo=p['source'],style=p['style_name']))
with (R/'proposed-rotation.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['slot_order','post_id','topic','style','planned_date','status'])
 for i,id in enumerate(rotation):
  p=next(p for p in posts if p['id']==id);w.writerow([i+1,id,p['topic'],p['style_name'],'','PROPOSED ONLY'])
rows=''.join(f'<tr><td>{i+1:02}</td><td>{id}</td><td>{next(p["topic"] for p in posts if p["id"]==id)}</td></tr>' for i,id in enumerate(rotation))
css='''*{box-sizing:border-box}body{margin:0;background:#edf2f5;color:#10243c;font:16px/1.5 Arial,sans-serif}header,main,footer{max-width:1480px;margin:auto;padding:34px}header{padding-top:52px}h1{font-size:clamp(35px,5vw,66px);line-height:1.05;letter-spacing:-2px;margin:12px 0 20px}h2{font-size:23px;line-height:1.2;min-height:56px;margin:14px 0 7px}.eyebrow{font-size:12px;letter-spacing:3px;font-weight:bold}.intro{max-width:800px;font-size:19px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}a{color:#165bea}button,.actions a{border:1px solid #b9c9d5;border-radius:7px;background:white;color:#10243c;padding:10px 15px;font-size:14px;cursor:pointer;text-decoration:none}button.active{background:#10243c;color:white}nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:28px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px}article{background:white;border-radius:13px;padding:20px;box-shadow:0 3px 12px #0a234008;overflow:hidden}.posthead{display:flex;justify-content:space-between;font-size:12px;font-weight:bold;letter-spacing:1px;color:#536c80}.style{font-size:13px;color:#536c80;margin:0 0 16px}.slides{display:flex;overflow-x:auto;gap:12px;scroll-snap-type:x mandatory}.slides a{flex:0 0 100%;scroll-snap-align:start}.slides img{width:100%;display:block;border-radius:4px}.hint{font-size:12px;color:#64778b}.caption{white-space:pre-line}.source{font-size:12px;overflow-wrap:anywhere;color:#64778b}.review{display:flex;justify-content:space-between;align-items:center;font-size:13px;margin:18px 0 10px}select,textarea{font:14px Arial;padding:8px;border:1px solid #b9c9d5;border-radius:5px}textarea{width:100%;resize:vertical}summary{cursor:pointer;font-weight:bold;font-size:14px}dialog{border:0;padding:0;background:#0a1220;color:white;max-width:95vw;max-height:98vh}dialog::backdrop{background:#000d}.viewer{display:flex;align-items:center;gap:10px;padding:12px}.viewer img{height:83vh;max-width:76vw;object-fit:contain}.viewer button{background:#20344c;color:white;border:0;font-size:25px}.viewtop{display:flex;justify-content:space-between;align-items:center;padding:8px 15px}section.plan{background:white;padding:28px;margin-top:35px;border-radius:12px;max-width:1000px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:8px;border-bottom:1px solid #dde5ec}[hidden]{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid{grid-template-columns:1fr}header,main,footer{padding:20px}.viewer{gap:2px;padding:2px}.viewer img{max-width:80vw;height:75vh}.viewer button{padding:6px}h2{min-height:0}}'''
js='''const DATA=POST_DATA;let pi=0,si=1;const dialog=document.querySelector('dialog');function show(){const p=DATA[pi];document.querySelector('#big').src=`images/${p.id}-${String(si).padStart(2,'0')}.jpg`;document.querySelector('#viewtitle').textContent=`${p.id} | ${si} of ${p.slides} | ${p.style_name}`;}function step(d){si+=d;if(si<1){pi=(pi+DATA.length-1)%DATA.length;si=DATA[pi].slides}if(si>DATA[pi].slides){pi=(pi+1)%DATA.length;si=1}show()}document.querySelectorAll('[data-post]').forEach(a=>a.addEventListener('click',ev=>{ev.preventDefault();pi=DATA.findIndex(p=>p.id===a.dataset.post);si=+a.dataset.slide;show();dialog.showModal()}));document.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='ArrowRight')step(1);if(e.key==='ArrowLeft')step(-1)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('article').forEach(a=>a.hidden=b.dataset.filter!=='all'&&a.dataset.style!==b.dataset.filter)});for(const el of document.querySelectorAll('[data-review],[data-note]')){const k='studio24-'+(el.dataset.review?'status-':'note-')+(el.dataset.review||el.dataset.note);el.value=localStorage.getItem(k)||'';el.addEventListener('input',()=>localStorage.setItem(k,el.value))}function downloadReviews(){const rows=DATA.map(p=>({id:p.id,status:localStorage.getItem('studio24-status-'+p.id)||'Not reviewed',notes:localStorage.getItem('studio24-note-'+p.id)||''}));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(rows,null,2)],{type:'application/json'}));a.download='studio-24-review-notes.json';a.click()}'''.replace('POST_DATA',json.dumps(posts))
(R/'index.html').write_text(f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dan Rose | 24-post review</title><style>{css}</style><header><div class="eyebrow">DAN ROSE / STUDIO FORMAT TEST / SEPTEMBER 29, 2026</div><h1>24 posts. Eight styles.<br>Ready for your review.</h1><p class="intro">Three posts in each approved direction. 18 single images, six complete carousels and 48 exports. Only shirtless original photographs. Your face and physique use the real photo pixels.</p><p>Nothing has been scheduled or published. Review notes stay in this browser until you download them.</p><div class="actions"><a href="studio-posts-24-review.zip" download>Download complete batch</a><a href="captions.txt">All captions</a><a href="source-map.json">Photo and crop mapping</a><a href="results-ledger.csv" download>Blank results ledger</a><button onclick="downloadReviews()">Download review notes</button><a href="https://drive.google.com/drive/folders/19en-2zvk9LWgeItK51A4pZeGzfP189Ih">Drive backup</a></div></header><main><nav><button class="active" data-filter="all">All 24</button>{''.join(f'<button data-filter="{i}">{i:02} {e(n)}</button>' for i,n in enumerate(['Original','Warm','Training','Outdoor','Magazine','Topic','Practical','Myth'],1))}</nav><div class="grid">{''.join(cards)}</div><section class="plan"><h2>Proposed test rotation</h2><p>Use the next available existing image-post slots after approval. Keep occupied slots intact. Each block mixes all eight styles. Place repeat attempts on different weekdays where slots allow. Dates stay blank until the batch is approved.</p><p>Compare every post after the same seven-day window. For educational posts, compare saves and shares relative to reach. For photography, inspect reach, profile visits and follows. Leave unavailable metrics blank. Count product trials or paying customers only when actual tracking supports attribution. This is a directional creative test; topics, poses, days and audience differences prevent a causal format verdict.</p><p><a href="proposed-rotation.csv">Download the proposed rotation</a></p><details><summary>Show all 24 slots</summary><table><tr><th>Slot</th><th>Post</th><th>Topic</th></tr>{rows}</table></details></section></main><footer>Editable text and image layers: templates/*.svg. Reusable backgrounds and cropped person layers: assets/. Full build instructions: <a href="README.txt">README.txt</a>.</footer><dialog><div class="viewtop"><span id="viewtitle"></span><button onclick="dialog.close()">Close</button></div><div class="viewer"><button onclick="step(-1)" aria-label="Previous image">‹</button><img id="big" alt="Full post preview"><button onclick="step(1)" aria-label="Next image">›</button></div></dialog><script>{js}</script></html>''')
print('Gallery, proposed rotation and blank ledger ready.')
